from taf.sbts.oam.coam.admin.schemas.infomodel.object import InfoModelObject, InfoModelObjectField


class NrCellHardware(InfoModelObject):
    """
    _L MO	- Objects created by services. Often referred to as HW objects.
    """
    lcr_id = InfoModelObjectField(name="lcrId")
    nr_cell_identity = InfoModelObjectField(name="nrCellIdentity")
    nr_cellgrp_dn = InfoModelObjectField(name="nrCellgrpDN", not_null=True)
    state_info = InfoModelObjectField(name="stateInfo")

    def __init__(self, dist_name, lcr_id, nr_cell_identity, nr_cellgrp_dn, state_info):
        self.lcr_id = lcr_id
        self.nr_cell_identity = nr_cell_identity
        self.nr_cellgrp_dn = nr_cellgrp_dn
        self.state_info = state_info

        super(NrCellHardware, self).__init__(dist_name=dist_name)

