class NrCellRuntime(InfoModelObject):
    """
    _R MO	- Runtime view object defined by external parties: NIDD, ADMIN, SYSADAPTER.
    """
    administrative_state = InfoModelObjectField(name="administrativeState")
    availability_status = InfoModelObjectField(name="availabilityStatus")
    fr_ref_list = InfoModelObjectField(name="frRefList")
    nr_cell_identity = InfoModelObjectField(name="nrCellIdentity")
    operational_state = InfoModelObjectField(name="operationalState")
    procedural_status = InfoModelObjectField(name="proceduralStatus")
    blocking_state = InfoModelObjectField(name="blockingState")
    usage_state = InfoModelObjectField(name="usageState")

    def __init__(self, dist_name, administrative_state, availability_status, fr_ref_list,
                 nr_cell_identity, operational_state, procedural_status, blocking_state, usage_state):
        self.administrative_state = administrative_state
        self.availability_status = availability_status
        self.fr_ref_list = fr_ref_list
        self.nr_cell_identity = nr_cell_identity
        self.operational_state = operational_state
        self.procedural_status = procedural_status
        self.blocking_state = blocking_state
        self.usage_state = usage_state

        super(NrCellRuntime, self).__init__(dist_name=dist_name)
